var CSS = `
.opencodian-status-bar { display: flex; align-items: center; justify-content: space-between; padding: 6px 10px; border-top: 1px solid var(--background-modifier-border); background: var(--background-primary); min-height: 28px; gap: 10px; flex-wrap: wrap; }
.opencodian-status { font-size: 11px; color: var(--text-muted); display: flex; align-items: center; gap: 2px; }
.opencodian-status.connected { color: var(--text-success); }
.opencodian-status.disconnected { color: var(--text-error); }
.opencodian-status-sep { color: var(--text-faint); margin: 0 2px; }
.opencodian-status-agent { color: var(--text-accent); }
.opencodian-status-model { color: var(--text-muted); font-style: italic; }
.opencodian-processing-indicator { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--text-muted); min-height: 16px; flex-wrap: wrap; }
.opencodian-processing-indicator.active { color: var(--text-accent); font-weight: 500; }
.opencodian-status-info { color: var(--text-normal); font-size: 10px; }
.opencodian-spinner { display: inline-block; width: 12px; height: 12px; border: 2px solid var(--text-muted); border-top-color: var(--text-accent); border-radius: 50%; animation: opencodian-spin 0.8s linear infinite; }
@keyframes opencodian-spin { to { transform: rotate(360deg); } }
.opencodian-esc-hint { font-size: 10px; color: var(--text-faint); background: var(--background-modifier-hover); padding: 2px 6px; border-radius: 3px; margin-left: 8px; }
`;
var OpencodianPlugin = class extends import_obsidian6.Plugin {
  settings = DEFAULT_SETTINGS;
  runtime = null;
  skillLoader = null;
  categoryRouter = null;
  markitdownTool = null;
  playwrightTool = null;
  async onload() {
    console.log("Loading Opencodian plugin");
    const style = document.createElement("style");
    style.id = "opencodian-styles";
    style.textContent = CSS;
    document.head.appendChild(style);
    await this.loadSettings();
    this.registerView(VIEW_TYPE_CHAT, (leaf) => new ChatView(leaf, this));
    this.addRibbonIcon("bot", "Opencodian", () => this.activateView());
    this.addCommand({
      id: "open-chat",
      name: "Open Chat",
      callback: () => this.activateView()
    });
    this.addCommand({
      id: "inline-edit",
      name: "Inline Edit (with selection)",
      editorCallback: (editor) => {
        openInlineEditModal(this.app, this, editor);
      }
    });
    this.addSettingTab(new OpencodianSettingTab(this.app, this));
    this.initializeRuntime();
    this.initializeSkills();
    this.initializeCategories();
    this.initializeCommands();
    this.initializeTools();
  }
  async onunload() {
    console.log("Unloading Opencodian plugin");
    if (this.runtime) {
      this.runtime.destroy();
      this.runtime = null;
    }
    if (this.playwrightTool) {
      this.playwrightTool.cleanup();
    }
    this.app.workspace.detachLeavesOfType(VIEW_TYPE_CHAT);
  }
  async loadSettings() {
    const data = await this.loadData();
    this.settings = normalizeSettings(data || {});
  }
  async saveSettings() {
    await this.saveData(this.settings);
  }
  async initializeRuntime() {
    const vaultPath = this.getVaultPath();
    const cliPath = this.settings.cliPath || void 0;
    this.runtime = createChatRuntime(vaultPath, cliPath);
    try {
      await this.runtime.initialize({
        model: this.settings.visibleModels?.[0],
        mode: this.settings.selectedMode
      });
      console.log("OpenCode runtime initialized, ready:", this.runtime.ready());
    } catch (error) {
      console.error("Failed to initialize runtime:", error);
    }
  }
  async initializeSkills() {
    this.skillLoader = new SkillLoader(this.app.vault);
    const { vaultSkills, userSkills, errors } = await this.skillLoader.loadAllSkills();
    if (errors.length > 0) {
      console.warn("Skill loading errors:", errors);
    }
    const registry = getSkillRegistry();
    registry.clear();
    if (vaultSkills) registry.register(vaultSkills);
    for (const skill of userSkills) registry.register(skill);
    console.log(`Loaded ${registry.size()} skills`);
  }
  initializeCategories() {
    this.categoryRouter = createCategoryRouter(this.settings);
  }
  async initializeCommands() {
    const commandManager = getSlashCommandManager(this);
    await commandManager.loadCommands();
  }
  initializeTools() {
    this.markitdownTool = new MarkitdownTool(this);
    this.markitdownTool.registerCommands();
    this.playwrightTool = new PlaywrightTool(this);
    this.playwrightTool.registerCommands();
  }
  async activateView() {
    const { workspace } = this.app;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_CHAT);
    if (leaves.length > 0) {
      workspace.revealLeaf(leaves[0]);
    } else {
      const leaf = workspace.getRightLeaf(false);
      if (leaf) {
        await leaf.setViewState({ type: VIEW_TYPE_CHAT, active: true });
        workspace.revealLeaf(leaf);
      }
    }
  }
  getVaultPath() {
    return this.app.vault.adapter.basePath;
  }
  async restartRuntime() {
    if (this.runtime) {
      this.runtime.destroy();
      this.runtime = null;
    }
    await this.initializeRuntime();
  }
};


